  "packages.onboarding.tours.installed.connectOnceAndPolythBuildsYourHome": "Свържете Home Assistant веднъж. Polyth прочита стаите и устройствата ви, задава няколко въпроса и създава табло Home според отговорите.",
  "packages.onboarding.tours.installed.pasteTheAddressAndALongLivedToken": "Поставете адреса и дълготраен токен. Polyth първо проверява връзката; токенът остава на сървъра и никога повече не се показва.",
  "packages.onboarding.tours.installed.homeAssistantAddress": "Адрес на Home Assistant",
  "packages.onboarding.tours.installed.openHomeFromTheSideRail": "Отворете Начало от страничната лента",
  "packages.onboarding.tours.installed.homeShowsYourRoomsAndFavourites": "„Начало“ показва стаите ви, любимите устройства и най-важното за вас. С молива местите, преоразмерявате и променяте стила на всяка карта.",
