  "packages.onboarding.tours.installed.letAgentsRunTheHouse": "Оставете агентите да управляват дома",
  "packages.onboarding.tours.installed.agentsSeeYourHomeByRoom": "Всеки агент вижда дома ви по стаи и управлява устройствата по име. В „Агенти“ решавате какво могат да правят; ключалките и алармите остават изключени, докато не ги разрешите.",
  "packages.onboarding.tours.installed.agentsTab": "Агенти",
