  "packages.onboarding.tours.installed.integrations": "Интеграции",
  "packages.onboarding.tours.installed.integrationsReportsExternalServiceReadinessThroughInstalled": "Интеграциите отчитат готовността за външни услуги чрез инсталирани CLI, без да съхраняват своите токени в Polyth.",
  "packages.onboarding.tours.installed.keepPreferredModelsFirst": "Запазете предпочитаните модели на първо място",
  "packages.onboarding.tours.installed.mcp": "MCP",
  "packages.onboarding.tours.installed.mcpManagesStdioAndHttpToolServers": "MCP управлява stdio и HTTP сървъри с инструменти, приложени към бекенд средата за изпълнение, със среда само за запис и секретни данни за заглавките.",
  "packages.onboarding.tours.installed.mcpServer": "+ MCP сървър",
