  "packages.onboarding.tours.installed.pasteACompatibleMcpserversBlockInspectThe": "Поставете съвместим блок mcpServers, проверете картографираните записи и импортирайте само след като предварителен преглед е валиден.",
  "packages.onboarding.tours.installed.pluginLibrary": "Библиотека с плъгини",
