  "packages.onboarding.tours.installed.pluginsCanContributeWidgetsCommandsToolsSettings": "Плъгините могат да предоставят уиджети, команди, инструменти, настройки и работни пространства от надеждни npm или локални източници.",
  "packages.onboarding.tours.installed.previewExistingConfiguration": "Преглед на съществуващата конфигурация",
  "packages.onboarding.tours.installed.providersModels": "Доставчици и модели",
  "packages.onboarding.tours.installed.providersModelsShowsWhatTheBackendDiscovered": "„Доставчици и модели“ показва какво е открил бекендът и контролира кои доставчици и модели се появяват в Polyth.",
  "packages.onboarding.tours.installed.referenceCredentialsWithoutRevealingThem": "Позоваване на идентификационни данни, без да ги разкривате",
  "packages.onboarding.tours.installed.reviewLabelsHandleNamesAndPurposesWithout": "Прегледайте етикетите, имената на дескрипторите и целите, без да връщате никаква секретна стойност.",
  "packages.onboarding.tours.installed.reviewStatusContributionCountsPermissionsAndLogs": "Прегледайте състоянието, броя на приносите, разрешенията и регистрационните файлове, преди да активирате или актуализирате разширение.",
  "packages.onboarding.tours.installed.roles": "Роли",
  "packages.onboarding.tours.installed.rolesConfiguresAnAgentSInstructionsModel": "Ролите конфигурират инструкциите, модела на агента и дали той води сесии или обработва делегирани задачи.",
  "packages.onboarding.tours.installed.savedHandles": "Запазени дескриптори",
  "packages.onboarding.tours.installed.savePromptsYouUseRepeatedly": "Запазване на често използвани промптове",
  "packages.onboarding.tours.installed.secureSafe": "Credential Vault",
  "packages.onboarding.tours.installed.secureSafeStoresValuesBehindReusableHandles": "Credential Vault съхранява стойности зад многократно използваеми дескриптори. Агентите могат да поискат дескриптор, но не могат да четат съхранените идентификационни данни.",
  "packages.onboarding.tours.installed.shapeHowEachRoleWorks": "Оформете как работи всяка роля",
