  "packages.onboarding.tours.installed.starTheModelsYouReachForMost": "Отбележете със звездичка моделите, които използвате най-често, за да се показват първи в менютата за избор.",
  "packages.onboarding.tours.installed.submitAValueOnce": "Изпратете стойност веднъж",
  "packages.onboarding.tours.installed.switchBetweenConnectedProvidersAndTheFull": "Превключвайте между свързани доставчици и пълния каталог, след което търсете или филтрирайте, преди да промените видимостта.",
  "packages.onboarding.tours.installed.tuneAReportedRole": "Настройване на докладвана роля",
  "packages.onboarding.tours.installed.verifyGithubReadiness": "Проверка на готовността за GitHub",
  "packages.onboarding.tours.installed.whenARepositoryIsDetectedOpenThe": "Когато бъде открито хранилище, отворете пълния преглед на задачите и pull request-ите от състоянието на интеграцията.",
  "packages.onboarding.tours.packages.eachTileUnderOptionalPackagesHasA": "Всяка плочка под „Опционални пакети“ има превключвател. Деактивирането на една от тях премахва незабавно страницата с настройки и уиджетите – няма какво да се преинсталира. Основните пакети остават включени.",
  "packages.onboarding.tours.packages.enableOnlyWhatYouNeed": "Активирайте само това, от което се нуждаете",
  "packages.onboarding.tours.packages.everyPackageWithAnIntroductionKeepsA": "Всеки пакет с въведение има бутон „Обиколка“ на своята плочка тук, така че можете да я възпроизведете отново, когато пожелаете – дори след като сте я пропуснали.",
