  "settings.commandline.trustCaution": "В този режим всяка програма на разрешените машини, включително агенти, изпълнявани тук, може да управлява Polyth от ваше име, включително да одобрява действия на агенти. Заявки през обратен прокси сървър или от браузър никога не се ползват с доверие. „Частна мрежа“ означава локални мрежови адреси (10.x, 172.16–31.x, 192.168.x), а не VPN или overlay диапазони.",
