  "shellintro.kicker": "Обиколка на интерфейса",
  "shellintro.stepCount": "{step} от {total}",
  "shellintro.steps": "Стъпки на обиколката",
  "shellintro.goToStep": "Към стъпка {step} от {total}",
  "shellintro.start": "Покажете ми",
  "shellintro.skip": "Пропускане на обиколката",
  "shellintro.finish": "Към работа",
  "shellintro.menuEntry": "Обиколка на интерфейса",
  "shellintro.addProjectNow": "Добавете проект сега",
  "shellintro.addProjectResumeNote": "Обиколката продължава, когато приключите.",
  "shellintro.projectReadyTitle": "Проектът ви е готов",
  "shellintro.projectReadyBody": "Ето го. Докато е избран, новите чатове могат да виждат файловете му и да работят с тях. Щракнете върху проект в този списък, за да превключвате между проектите.",
  "shellintro.projectReadyPhoneBody": "Вече е в това меню. Докато е избран, новите чатове могат да виждат файловете му и да работят с тях. Докоснете тук по всяко време, за да смените проекта.",
  "shellintro.openAppearance": "Отваряне на „Външен вид“",
  "shellintro.welcomeTitle": "Добре дошли в Polyth",
  "shellintro.welcomeBody": "Можете да започнете веднага — няма нищо за настройване и не можете да счупите нищо. Тази едноминутна обиколка показва къде да пишете, къде се пазят чатовете ви и как да променяте нещата по-късно.",
  "shellintro.startTitle": "Започнете направо тук",
  "shellintro.startBody": "Напишете какво ви трябва със свои думи — въпрос, задача или чернова — и изпратете. Отговорът се появява точно тук. Чатовете ви виждате само вие.",
  "shellintro.projectsTitle": "Чатове и проекти",
  "shellintro.projectsBody": "Тук се пазят всичките ви чатове, за да можете да се върнете към всеки от тях. Проектите, които добавите по-късно, също ще се появят тук, всеки със свои чатове. Малка точка означава, че асистентът работи или чака отговора ви.",
  "shellintro.addProjectTitle": "Проекти — когато ви потрябват",
  "shellintro.addProjectBody": "Не е нужен, за да започнете. Проектът е просто папка с вашите файлове — документи, снимки, уебсайт или код. Добавете такъв и асистентът ще може да отваря и редактира тези файлове, когато го помолите. (Разработчиците могат да свържат и Git хранилище или друг компютър през SSH.)",
  "shellintro.topRailTitle": "Инструменти отгоре",
  "shellintro.topRailBody": "Бутони за вашите инструменти. Всеки се отваря до чата, така че разговорът остава на видно място.",
  "shellintro.rightRailTitle": "Още инструменти встрани",
  "shellintro.rightRailBody": "Още инструменти, включително добавките, които инсталирате. Всеки се отваря като страничен панел; влачете ръба му, за да го разширите.",
  "shellintro.toolsTitle": "Инструменти",
  "shellintro.dragTitle": "Поставете бутоните където искате",
  "shellintro.dragBody": "Влачете бутон, за да го преместите по лентата му или в друга. За да го премахнете, издърпайте го настрани и пуснете — по-късно можете да го върнете. На сензорен екран първо задръжте.",
  "shellintro.customizeTitle": "Функции по ваш вкус",
  "shellintro.customizeBody": "Отворете менюто, към което сочи стрелката, и включете „Режим на редактиране“: на всяка част от екрана се появява молив, с който добавяте, премахвате или местите бутони и уиджети. Останалото е в Настройки: асистенти и AI модели, добавки (пакети) и клавишни комбинации.",
  "shellintro.appearanceTitle": "Външен вид по ваш вкус",
  "shellintro.appearanceBody": "В Настройки → Външен вид избирате цветове, светъл или тъмен режим, размер на текста, шрифтове, тапет и други. Всеки проект може да има и собствена икона.",
  "shellintro.projectsPhoneTitle": "Чатове и проекти",
  "shellintro.projectsPhoneBody": "Докоснете тук, за да видите чатовете си. Проектите, които добавите по-късно, също ще се появят тук. Малка точка означава, че асистентът работи или чака отговора ви.",
  "shellintro.addProjectPhoneBody": "Не е нужен, за да започнете. Проектът е просто папка с вашите файлове — документи, снимки, уебсайт или код. Бутонът + в това меню добавя такъв; после асистентът ще може да отваря и редактира тези файлове, когато го помолите.",
  "shellintro.toolsPhoneTitle": "Инструменти",
  "shellintro.toolsPhoneBody": "Тук са вашите инструменти. Всеки се отваря на цял екран; докоснете „Назад“, за да се върнете към чата.",
  "shellintro.customizePhoneBody": "На компютър „Режим на редактиране“ в менюто ви позволява да добавяте, премахвате или местите бутони. Тук също в Настройки избирате асистенти и AI модели, добавки (пакети) и други.",
  "composer.manageHarnesses": "Управление на харнесите",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "Моделите идват от вашите харнеси",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth комуникира с моделите чрез агентски харнеси. Безплатните модели на OpenCode работят без акаунт. Предпочитате Claude Code, Codex или друг агент? Инсталирайте и настройте предпочитаните на страницата „Харнеси“ — това не е задължително.",
  "packages.onboarding.tours.installed.openHarnesses": "Отворете „Харнеси“",
  "desktopupdate.availableTitle": "Наличен е Polyth {version}",
  "desktopupdate.availableBody": "Изтеглете го сега. Ще се инсталира при рестартиране на Polyth.",
